(async()=>{const url=new URL('/echo',location.href);url.hostname='localhost';const out={};for(const credentials of ['omit','same-origin','include'])out[credentials]=await fetch(url.href,{credentials}).then(r=>r.json());for(const credentials of [false,true])out['xhr-'+credentials]=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('GET',url.href);x.withCredentials=credentials;x.onload=()=>resolve(JSON.parse(x.responseText));x.onerror=()=>reject(Error('xhr'));x.send()});return out})()
